alter table if exists fieldpro.quotes drop constraint if exists quotes_status_check;
update fieldpro.quotes set status='draft' where status not in ('draft','sent','pending','accepted','refused','expired','converted_to_invoice');
alter table if exists fieldpro.quotes add constraint quotes_status_check check (status in ('draft','sent','pending','accepted','refused','expired','converted_to_invoice'));
alter table if exists fieldpro.invoices add column if not exists source_quote_id uuid references fieldpro.quotes(id) on delete set null;
create unique index if not exists uq_invoices_source_quote on fieldpro.invoices(source_quote_id) where source_quote_id is not null;
alter table if exists fieldpro.document_templates add column if not exists editor_config jsonb not null default '{}'::jsonb;
create table if not exists fieldpro.template_versions (id uuid primary key default gen_random_uuid(), workspace_id uuid not null references fieldpro.workspaces(id) on delete cascade, template_id uuid not null references fieldpro.document_templates(id) on delete cascade, version_no integer not null, structure_json jsonb not null default '{}'::jsonb, editor_config jsonb not null default '{}'::jsonb, created_by uuid, created_at timestamptz not null default now(), unique(template_id, version_no));
create index if not exists idx_template_versions_ws on fieldpro.template_versions(workspace_id);create table if not exists fieldpro.quote_reminders (id uuid primary key default gen_random_uuid(), workspace_id uuid not null references fieldpro.workspaces(id) on delete cascade, quote_id uuid not null references fieldpro.quotes(id) on delete cascade, created_by uuid, created_at timestamptz not null default now(), status text not null default 'prepared', note text); create index if not exists idx_quote_reminders_quote on fieldpro.quote_reminders(quote_id, created_at desc);